import {
  computed,
  ref,
  useTemplateRef,
  VNodeRef,
  type SVGAttributes,
} from "vue";
import Numogram, { getMeshTagData, type ColorConfig } from "../../Numogram";
import Dialog, { type DialogState } from "primevue/dialog";
import Syzygy from "./NumogramParts/Syzygy.vue";
import CCurrent from "./NumogramParts/Current.vue";
import Label from "primevue/label";
import Fieldset from "primevue/fieldset";
import Demon from "./NumogramParts/Displays/Demon.vue";
import Gate from "./NumogramParts/Gate.vue";
import ZoneDisplay from "./NumogramParts/Displays/ZoneDisplay.vue";
import CurrentDisplay from "./NumogramParts/Displays/CurrentDisplay.vue";
import GateDisplay from "./NumogramParts/Displays/GateDisplay.vue";
interface Props {
  GateColor: string;
  colConfig: ColorConfig;
  width?: string | number;
  height?: string | number;
  class?: string;
}
const visible = ref<boolean>(false);

const {
  width = "500",
  height = "897.06",

  class: className = "",
  GateColor = "red",
  colConfig = {
    gateCol: "red",
    numColor: "white",
    strokeCol: "white",
    fillCol: "none",
    currentsCol: "steelblue",
  },
  ...props
} = defineProps<Props>();
let hovered = ref<{
  type: "zone" | "current" | "gate";
  id: string | number;
} | null>(null);
const aspectRatio = 34 / 61;
// Determine if an element should be highlighted or dimmed
const isDimmed = (type: "zone" | "current" | "gate", id: string) => {
  if (!hovered.value) return false;
  if (hovered.value.type === type && hovered.value.id === id) return false;

  // Syzygy highlighting logic
  if (hovered.value.type === "zone") {
    const activeZone = hovered.value.id;
    const syzygyTwin = 9 - Number(activeZone);
    if (type === "zone" && (id == activeZone || id == String(syzygyTwin)))
      return false;
    if (
      type === "current" &&
      idNum.value &&
      id ===
        `${Math.max(Number(activeZone), syzygyTwin)}::${Math.min(idNum.value, syzygyTwin)}`
    )
      return false;
  }

  if (hovered.value.type === "current" && typeof hovered.value.id == "string") {
    const [a, b] = hovered.value.id.split("::").map(Number);
    if (hovered.value.id == id) return true;
    if (type === "zone" && (id === String(a) || id === String(b))) return false;
  }

  if (hovered.value.type === "gate") {
    const idNum = Number(hovered.value.id);
    const gateData = Numogram.Gates[idNum];
    if (
      type === "zone" &&
      (idNum === gateData.zone.id || idNum === gateData.reduces)
    )
      return false;
  }

  return true;
};
const curSyz = computed(() => {
  if (
    hovered.value &&
    hovered.value.type === "current" &&
    typeof hovered.value.id === "string"
  ) {
    if (hovered.value.id == "5::4" || hovered.value.id == "4::5")
      return Numogram.Currents["5::4"];
    else if (hovered.value.id == "6::3" || hovered.value.id == "3::6")
      return Numogram.Currents["6::3"];
    else if (hovered.value.id == "7::2" || hovered.value.id == "2::7")
      return Numogram.Currents["7::2"];
    else if (hovered.value.id == "8::1" || hovered.value.id == "1::8")
      return Numogram.Currents["8::1"];
    else if (hovered.value.id == "9::0" || hovered.value.id == "0::9")
      return Numogram.Currents["9::0"];
    return null;
  }
  return null;
});

const idNum = computed(() => {
  if (
    hovered.value &&
    (hovered.value.type == "zone" || hovered.value.type == "gate")
  ) {
    if (hovered.value.id == 0 || hovered.value.id == "0") return 0;
    else if (hovered.value.id) return Number(hovered.value.id);
  }
  return null;
});

const handleHover = (
  type: "zone" | "current" | "gate",
  id: string | number,
  event: MouseEvent | PointerEvent,
) => {
  hovered.value = { type, id };
  console.log("Type ", type);
  console.log("Id ", id);
  if (type == "zone" || type == "current" || type == "gate")
    visible.value = true;
};

const handleLeave = () => {
  hovered.value = null;
};

const meshTag = computed(() => {
  if (hovered.value?.id && idNum.value) {
    return getMeshTagData(idNum.value);
  }
  return null;
});
